<script lang="ts">
import {tick,onDestroy} from 'svelte';import {TutorialPanel,CoachMark,getActiveModal,isUsableFocusTarget,restoreCompositionFocus,getFocusAncestors} from '@unofficial-krds/svelte';import type {TutorialStopDetails} from '@unofficial-krds/svelte';let {componentId,state:s,emit,patch}:{componentId:string;state:Record<string,any>;emit:(name:string,detail:any,next?:Record<string,any>)=>void;patch:(next:Record<string,any>)=>void}=$props();const host=$derived(s.__host??{});const tutorial=$derived(componentId==='tutorial-panel');const linked=$derived(tutorial||host.linkedTutorial===true);const steps=$derived(s.steps??s.tasks?.find((task:any)=>task.id===s.activeTaskId)?.steps??s.tasks?.[0]?.steps??[]);const tasks=$derived(s.tasks??[{id:'apply',title:'예제 신청하기',steps}]);const running=$derived(Boolean(s.running??s.open??s.defaultOpen??tutorial));const panelOpen=$derived(tutorial?Boolean(s.open??s.defaultOpen??true):Boolean(s.__tutorialOpen??host.panelOpen??(host.layout==='narrow-modal')));const activePanel=$derived(s.activePanel??s.__tutorialActivePanel??host.activePanel??(host.layout==='narrow-modal'&&!tutorial?'help':'tutorial'));const narrowHelp=$derived(linked&&host.layout==='narrow-modal'&&!tutorial);const currentStep=$derived(tutorial?s.activeStepId:s.stepId??s.defaultStepId??steps[0]?.id);const boundaries=$derived(s.boundaries??steps.map((step:any)=>({targetId:step.targetId,insertionBoundaryId:`${step.targetId}-after`})));let values=$state<Record<string,string>>({}),verified=$state(false);
let stopRevision=0,alive=true,delegated=$state(false);let saved:HTMLElement|null=null;let ancestors:HTMLElement[]=[];onDestroy(()=>{alive=false;stopRevision++;});
function stop(detail:TutorialStopDetails){if(!running)return;saved=document.activeElement instanceof HTMLElement?document.activeElement:null;ancestors=getFocusAncestors(saved);emit('stop',detail);if(host.acceptStop===false||host.acceptRunningFalse===false)return;delegated=true;const token=++stopRevision;const next:Record<string,any>={running:false};if(host.acceptOpenTrue!==false&&host.acceptPanelExposure!==false)next[tutorial?'open':'__tutorialOpen']=true;if(host.acceptTutorialTab!==false&&host.acceptPanelExposure!==false)next[tutorial?'activePanel':'__tutorialActivePanel']='tutorial';patch(next);void tick().then(()=>{if(!alive||token!==stopRevision||running)return;const modal=getActiveModal(document);const preferred=document.getElementById(s.startActionId);const fallback=modal?(document.getElementById(`${s.fallbackFocusId}-inside`)??document.getElementById(s.fallbackFocusId)):document.getElementById('tutorial-panel-opener')??document.getElementById(s.fallbackFocusId);const target=isUsableFocusTarget(preferred)&&(!modal||modal.contains(preferred))?preferred:isUsableFocusTarget(fallback)&&(!modal||modal.contains(fallback))?fallback:saved;restoreCompositionFocus(document,target,s.fallbackFocusId,ancestors);delegated=false;});}

async function standaloneOpen(detail:{open:boolean}){const before=document.activeElement instanceof HTMLElement?document.activeElement:null;emit('openChange',detail,!detail.open&&host.acceptStop===false?undefined:{open:detail.open,running:detail.open});await tick();if(!detail.open&&!running){const active=document.activeElement;if(isUsableFocusTarget(active)&&active!==document.body)return;const preferred=document.getElementById(s.startActionId);restoreCompositionFocus(document,isUsableFocusTarget(preferred)?preferred:before,s.fallbackFocusId,getFocusAncestors(before));}}

async function verify(){await tick();return host.targetActionVerified===true&&verified;}
</script><div>{#if !linked&&!running&&host.startActionPresent!==false}<button id={s.startActionId} type="button" onclick={()=>emit('openChange',{open:true},{open:true,running:true})}>따라하기 시작</button>{/if}{#if linked}<TutorialPanel id="tutorial-panel-shell" delegateEntry={delegated} {tasks} activeTaskId={s.activeTaskId??'apply'} activeStepId={currentStep??null} open={panelOpen} {running} {activePanel} startActionId={s.startActionId} fallbackFocusId={s.fallbackFocusId} startActionPresent={host.startActionPresent!==false&&(tutorial||panelOpen||running)} openerId="tutorial-panel-opener" onStart={detail=>emit('start',detail,{running:true,activeTaskId:detail.taskId,activeStepId:detail.stepId})} onOpenChange={detail=>tutorial?emit('openChange',detail,{open:detail.open}):patch({__tutorialOpen:detail.open})} onActivePanelChange={detail=>emit('activePanelChange',detail,tutorial?{activePanel:detail.value}:{__tutorialActivePanel:detail.value})} onStop={stop}>{#snippet help()}<button type="button" id={`${s.fallbackFocusId}-inside`}>도움말 내부 작업</button>{#if narrowHelp}{@render targets()}{/if}{/snippet}</TutorialPanel>{/if}{#snippet targets()}{#each steps as item(item.id)}<label for={item.targetId}>{item.title}</label>{#if !host.targetRemoved}{#if item.requiresAction}<button id={item.targetId} type="button" onclick={()=>verified=host.targetActionVerified===true}>{item.title}</button>{:else}<input id={item.targetId} aria-label={item.title} bind:value={values[item.targetId]}/>{/if}{/if}<span id={boundaries.find((b:any)=>b.targetId===item.targetId)?.insertionBoundaryId}></span>{/each}{/snippet}{#if !narrowHelp}{@render targets()}{/if}<CoachMark panelId={linked?'tutorial-panel-shell':undefined} {steps} {boundaries} open={running} stepId={currentStep} startActionId={s.startActionId} fallbackFocusId={s.fallbackFocusId} onTargetAction={verify} onStepChange={detail=>emit('stepChange',detail,{[tutorial?'activeStepId':'stepId']:detail.id})} onStop={linked?stop:undefined} onOpenChange={linked?